WITH knowledge_author AS (
  SELECT id
  FROM users
  ORDER BY CASE role WHEN 'admin' THEN 1 WHEN 'agent' THEN 2 ELSE 3 END, id
  LIMIT 1
),
seed AS (
  SELECT 'Problemas para iniciar sesión en Microsoft Teams' AS title, '1. Confirma que el equipo tiene conexión a Internet y que puedes abrir otros sitios de trabajo. 2. Revisa que estás usando la cuenta laboral correcta y vuelve a escribir la contraseña sin compartirla con nadie. 3. Cierra Teams por completo, ábrelo de nuevo e intenta iniciar sesión. 4. Si la cuenta está bloqueada, la autenticación multifactor falla o el problema persiste, solicita ayuda e indica el mensaje de error exacto. Usa siempre el portal oficial de autoservicio de tu organización para recuperar la cuenta.' AS content, 'Colaboración' AS category, 'Teams, inicio de sesión, acceso, contraseña, cuenta laboral' AS keywords
  UNION ALL SELECT 'Problemas de cámara, micrófono o audio en Teams', '1. Comprueba que la cámara o el micrófono no estén cubiertos, silenciados ni desconectados. 2. En la configuración de dispositivos de Teams, selecciona el micrófono, altavoz y cámara correctos y utiliza la prueba disponible. 3. Cierra otras aplicaciones que puedan estar usando la cámara o el audio. 4. Desconecta y vuelve a conectar el dispositivo externo o prueba los dispositivos integrados. 5. Reinicia Teams. Si persiste, anota el modelo del dispositivo, la aplicación afectada y si el problema ocurre en todas las reuniones.' , 'Colaboración', 'Teams, cámara, micrófono, audio, altavoz, reunión' 
  UNION ALL SELECT 'No puedo entrar a una reunión de Teams', '1. Abre el enlace desde Teams o el calendario laboral y comprueba que estás en la cuenta correcta. 2. Verifica la fecha y hora del equipo y la conexión a Internet. 3. Si aparece una sala de espera, espera a que el organizador admita tu entrada. 4. Comprueba si la reunión requiere una cuenta o permiso específico. 5. Si el enlace indica que la reunión no existe o no tienes permiso, contacta al organizador y comparte el mensaje mostrado sin incluir códigos de acceso privados.' , 'Colaboración', 'Teams, reunión, enlace, sala de espera, permiso, calendario' 
  UNION ALL SELECT 'Outlook no envía ni recibe correos', '1. Comprueba la conexión a Internet y revisa si Outlook muestra que está trabajando sin conexión. 2. Busca el mensaje en Borradores y en Bandeja de salida para identificar si quedó pendiente. 3. Confirma que el destinatario está escrito correctamente y que el buzón no está lleno. 4. Prueba Outlook en la web si tu organización lo ofrece. 5. Si solo falla un destinatario, anota cualquier aviso de entrega. No envíes repetidamente un mensaje con información sensible mientras verificas si ya salió.' , 'Correo', 'Outlook, correo, enviar, recibir, bandeja de salida, buzón' 
  UNION ALL SELECT 'Restablecer una contraseña olvidada', 'Utiliza únicamente el portal oficial de recuperación o autoservicio que haya indicado tu organización. Comprueba que la dirección y el dominio del portal sean los oficiales antes de introducir datos. Sigue la verificación de identidad y crea una contraseña nueva que no reutilices en otros servicios. Si ya no tienes acceso al método de verificación, la cuenta está bloqueada o sospechas que otra persona conoce la contraseña, contacta al equipo de soporte por un canal oficial. El soporte nunca debe pedirte que le envíes tu contraseña.' , 'Acceso', 'contraseña, restablecer, recuperar, cuenta bloqueada, autoservicio' 
  UNION ALL SELECT 'No recibo la notificación de autenticación multifactor', '1. Comprueba que el teléfono tiene conexión, notificaciones permitidas y fecha y hora automáticas. 2. Abre la aplicación de autenticación manualmente y actualiza la solicitud si está disponible. 3. Confirma que estás aprobando el inicio de sesión que acabas de iniciar. 4. Si cambiaste de teléfono o perdiste acceso a la aplicación, utiliza el proceso oficial de recuperación de tu organización. Nunca apruebes una solicitud que no hayas iniciado ni compartas códigos de verificación con otra persona.' , 'Seguridad', 'MFA, autenticación multifactor, código, notificación, aplicación autenticadora' 
  UNION ALL SELECT 'La cuenta aparece bloqueada', 'Deja de repetir intentos de inicio de sesión para evitar prolongar el bloqueo. Comprueba que estás usando la cuenta correcta y que el teclado no tiene activadas teclas inesperadas. Espera el periodo indicado o utiliza el autoservicio oficial de desbloqueo si está habilitado. Si no puedes completar la verificación, abre una solicitud al equipo de soporte e incluye el nombre de usuario laboral, la hora aproximada y el texto del aviso, pero nunca la contraseña ni códigos de verificación.' , 'Acceso', 'cuenta bloqueada, inicio de sesión, desbloquear, acceso' 
  UNION ALL SELECT 'Cómo reconocer y reportar un correo sospechoso', 'Desconfía de mensajes inesperados que exijan actuar con urgencia, pidan contraseñas o códigos, cambien instrucciones de pago o incluyan enlaces y archivos no solicitados. No abras el enlace ni el adjunto, no respondas y no introduzcas credenciales. Usa la opción oficial de reporte de correo sospechoso o informa al equipo de seguridad por el canal aprobado. Si ya abriste el archivo, seguiste un enlace o compartiste datos, avisa de inmediato y describe qué ocurrió y cuándo. No reenvíes el mensaje a otros compañeros.' , 'Seguridad', 'phishing, correo sospechoso, fraude, enlace, adjunto, reportar' 
  UNION ALL SELECT 'Perdí o me robaron el equipo de trabajo', 'Informa la pérdida o el robo inmediatamente al equipo de soporte o seguridad mediante un canal oficial. Indica cuándo y dónde ocurrió, el tipo de equipo y si estaba desbloqueado, sin publicar esos datos en canales abiertos. Si tienes acceso a las herramientas oficiales de seguridad, sigue las instrucciones para bloquear o localizar el dispositivo. Cambia credenciales desde otro dispositivo confiable solo siguiendo el procedimiento de la organización. No intentes recuperar físicamente un dispositivo robado ni elimines información por tu cuenta.' , 'Seguridad', 'equipo perdido, robo, portátil, teléfono, dispositivo, bloqueo remoto' 
  UNION ALL SELECT 'OneDrive no sincroniza archivos', '1. Comprueba la conexión a Internet y confirma que OneDrive está iniciado con la cuenta laboral correcta. 2. Revisa el icono de sincronización y abre la lista de errores para identificar el archivo afectado. 3. Confirma que el nombre y la ruta no excedan los límites indicados por la aplicación y que tengas espacio disponible. 4. Cierra y vuelve a abrir la aplicación de sincronización. 5. No borres la carpeta local ni desvincules la cuenta si hay cambios pendientes. Si el error continúa, registra el nombre del archivo y el mensaje mostrado.' , 'Colaboración', 'OneDrive, sincronización, archivos pendientes, nube, espacio' 
  UNION ALL SELECT 'No tengo permiso para abrir un archivo compartido', 'Comprueba que has iniciado sesión con la cuenta laboral a la que se compartió el archivo. Solicita al propietario que confirme que el enlace sigue activo y que concedió el nivel de acceso adecuado. Si el archivo pertenece a un sitio o equipo, pide acceso al propietario del recurso por el canal habitual. No copies información confidencial a una cuenta personal para evitar el control de permisos. Incluye el enlace interno del recurso en tu ticket solo si las normas de tu organización lo permiten.' , 'Acceso', 'archivo compartido, permiso, acceso, SharePoint, OneDrive, carpeta' 
  UNION ALL SELECT 'No puedo conectarme a la red Wi-Fi de trabajo', '1. Comprueba que el Wi-Fi esté activado y que el modo avión esté desactivado. 2. Confirma que seleccionaste la red corporativa correcta y no una red con nombre parecido. 3. Desconéctate y vuelve a conectarte usando el método de autenticación aprobado. 4. Reinicia el adaptador desde la configuración del sistema o reinicia el equipo si es seguro hacerlo. 5. Si varios compañeros tienen el mismo problema, informa también la ubicación y la hora. No intentes evadir los controles de acceso conectándote a redes no autorizadas.' , 'Red', 'Wi-Fi, wifi, red inalámbrica, conexión, red corporativa, Internet' 
  UNION ALL SELECT 'La VPN no conecta o se desconecta', 'Comprueba primero que Internet funcione sin la VPN. Abre el cliente VPN aprobado y confirma que utilizas el perfil y la cuenta de trabajo correctos. Completa la autenticación multifactor solo si tú iniciaste la conexión. Reinicia el cliente y el equipo si no hay tareas pendientes. Si aparece un error de certificado, permiso o dispositivo no compatible, no cambies la configuración de seguridad: contacta a soporte con el texto exacto, la hora y si estás dentro o fuera de la oficina.' , 'Red', 'VPN, acceso remoto, conexión segura, certificado, desconexión' 
  UNION ALL SELECT 'La impresora no imprime o deja trabajos pendientes', '1. Comprueba que la impresora esté encendida, sin errores visibles y conectada a la red o al cable previsto. 2. Revisa que elegiste la impresora correcta y que el trabajo no esté pausado. 3. Comprueba si otros usuarios pueden imprimir para diferenciar un problema del equipo de uno de la impresora. 4. Cancela solo tus propios trabajos atascados y vuelve a enviar una página de prueba. 5. Si muestra atasco, tóner o mantenimiento, sigue las instrucciones visibles o solicita asistencia. No abras componentes internos si no estás autorizado.' , 'Hardware', 'impresora, imprimir, cola de impresión, atasco, tóner' 
  UNION ALL SELECT 'Una aplicación de Windows se queda congelada', 'Espera unos segundos para confirmar que la aplicación no esté procesando una tarea. Si sigue sin responder, guarda primero el trabajo si la aplicación vuelve a reaccionar. Cierra únicamente esa aplicación desde las opciones normales del sistema y vuelve a abrirla. Reinicia el equipo cuando no haya actualizaciones o transferencias en curso. Si ocurre repetidamente, anota el nombre y versión de la aplicación, la acción realizada y cualquier mensaje de error. No finalices procesos del sistema que no reconozcas.' , 'Windows', 'Windows, aplicación congelada, no responde, bloqueo, programa' 
  UNION ALL SELECT 'Windows solicita reiniciar o instalar actualizaciones', 'Guarda tus documentos y conecta el portátil a la corriente antes de iniciar una actualización. Usa las opciones de actualización administradas por tu organización y no apagues el equipo mientras el proceso esté en curso. Si el reinicio se repite, queda detenido durante mucho tiempo o muestra un código de error, anota el código y la hora y contacta a soporte. No desactives las actualizaciones ni instales controladores desde sitios no oficiales.' , 'Windows', 'Windows Update, actualización, reinicio, parche, actualización detenida' 
  UNION ALL SELECT 'El equipo está lento', '1. Guarda tu trabajo y reinicia el equipo si lleva mucho tiempo encendido. 2. Comprueba si una aplicación concreta consume recursos y cierra las que no estés usando. 3. Asegúrate de tener espacio libre razonable y de que las actualizaciones no estén instalándose. 4. Comprueba que el equipo no esté demasiado caliente y que las rejillas de ventilación no estén tapadas. 5. Si la lentitud empezó después de instalar una aplicación o aparece un aviso de seguridad, contacta a soporte. No instales utilidades de limpieza no aprobadas.' , 'Windows', 'equipo lento, rendimiento, CPU, memoria, portátil, lentitud' 
  UNION ALL SELECT 'El disco del equipo indica que queda poco espacio', 'Revisa el almacenamiento desde la configuración del sistema e identifica archivos personales temporales que puedas eliminar de forma segura. Vacía la papelera solo después de comprobar su contenido y mueve documentos de trabajo únicamente a ubicaciones corporativas aprobadas. No borres carpetas del sistema, perfiles de aplicaciones ni archivos de trabajo que no estén respaldados. Si el espacio sigue agotado, solicita orientación sobre almacenamiento o ampliación al equipo de soporte.' , 'Windows', 'espacio en disco, almacenamiento lleno, disco, archivos temporales' 
  UNION ALL SELECT 'Solicitar la instalación de un programa', 'Comprueba primero si el programa ya está disponible en el catálogo o portal de software aprobado por tu organización. Si no aparece, crea una solicitud indicando el nombre exacto, proveedor, versión necesaria, propósito laboral y fecha en que se requiere. Incluye el nombre del equipo solo si te lo piden. Espera la aprobación e instalación por el método corporativo. No descargues instaladores desde anuncios, sitios de terceros o enlaces enviados por desconocidos.' , 'Software', 'instalar programa, software, aplicación, catálogo, aprobación' 
  UNION ALL SELECT 'El monitor externo o la estación de acoplamiento no funciona', '1. Comprueba que el monitor y la estación de acoplamiento tengan alimentación. 2. Verifica que el cable esté conectado en ambos extremos y que el monitor tenga seleccionada la entrada correcta. 3. Desconecta y vuelve a conectar el cable o la estación de acoplamiento. 4. Usa la opción de detectar pantallas del sistema operativo y revisa el modo de duplicar o extender. 5. Si el problema sigue, prueba un cable conocido y anota el modelo del monitor y del equipo. No fuerces conectores ni desmontes el dispositivo.' , 'Hardware', 'monitor externo, dock, docking station, pantalla, USB-C, HDMI' 
  UNION ALL SELECT 'No puedo usar el escritorio remoto', 'Confirma que tienes conexión a Internet y que estás usando la aplicación remota aprobada por tu organización. Comprueba que iniciaste sesión con la cuenta laboral correcta y que tu cuenta tiene permiso para el recurso solicitado. Si estás fuera de la oficina, verifica si el procedimiento requiere VPN antes de abrir la conexión remota. Registra el texto exacto del error y la hora. No compartas códigos de acceso ni habilites herramientas remotas de terceros.' , 'Acceso', 'escritorio remoto, remoto, VPN, acceso, conexión remota' 
  UNION ALL SELECT 'Una página o aplicación web no carga', '1. Recarga la página y comprueba si otros sitios de trabajo abren. 2. Confirma que estás usando la dirección oficial y la cuenta correcta. 3. Prueba una ventana privada o un navegador aprobado distinto para identificar si el problema depende de la sesión. 4. Si solo falla una aplicación, anota su nombre, la hora y el mensaje que aparece. No ignores avisos de certificado ni introduzcas la contraseña en una página cuya dirección no puedas verificar.' , 'Software', 'navegador, página no carga, aplicación web, certificado, caché' 
  UNION ALL SELECT 'Cómo describir un problema al crear un ticket', 'Incluye un asunto corto que describa el síntoma. En la descripción indica qué intentabas hacer, qué ocurrió, qué esperabas que ocurriera, cuándo empezó y si afecta a otras personas. Añade los pasos que reproducen el problema y el texto o código de error. Usa capturas solo si están permitidas y elimina datos personales, contraseñas, códigos y contenido confidencial antes de adjuntarlas. Indica si ya probaste una solución y el resultado. No incluyas secretos en el ticket.' , 'Buenas prácticas', 'crear ticket, describir problema, error, captura, pasos para reproducir' 
  UNION ALL SELECT 'El equipo no enciende', 'Comprueba que el adaptador de corriente esté conectado a una toma que funcione y que sus conexiones estén firmes. Si es un portátil, déjalo conectado unos minutos y revisa si aparece algún indicador de carga. Desconecta accesorios no esenciales y prueba el encendido una vez más. Si notas olor a quemado, líquido, batería hinchada o calor inusual, deja de usarlo y contacta a soporte de inmediato. No abras el equipo ni retires la batería si no estás autorizado.' , 'Hardware', 'equipo no enciende, portátil, batería, cargador, alimentación' 
  UNION ALL SELECT 'Cómo proteger información sensible al trabajar', 'Usa solo cuentas, equipos, aplicaciones y ubicaciones aprobadas por tu organización. Bloquea la pantalla cuando te alejes y guarda documentos en el espacio corporativo autorizado. No compartas contraseñas, códigos MFA, claves de recuperación ni enlaces con acceso abierto. Antes de enviar archivos, confirma destinatarios y permisos. Reporta de inmediato una exposición accidental, pérdida de equipo o solicitud inusual de acceso. Sigue las políticas internas cuando sean más específicas que esta guía general.' , 'Seguridad', 'información sensible, privacidad, contraseña, permisos, datos' 
  UNION ALL SELECT 'Cómo compartir la pantalla de forma segura en una reunión', 'Antes de compartir, cierra documentos, conversaciones y notificaciones que no deban ver los participantes. Siempre que sea posible comparte solo la ventana necesaria en lugar de todo el escritorio. Comprueba que seleccionaste la reunión correcta y detén la compartición al terminar. No muestres contraseñas, datos personales, información de clientes ni material confidencial a personas sin autorización.' , 'Colaboración', 'compartir pantalla, Teams, reunión, privacidad, escritorio' 
)
INSERT INTO knowledge_articles (author_id, title, content, category, keywords)
SELECT knowledge_author.id, seed.title, seed.content, seed.category, seed.keywords
FROM knowledge_author CROSS JOIN seed
WHERE NOT EXISTS (
  SELECT 1 FROM knowledge_articles existing WHERE existing.title = seed.title
);